import React from 'react';
import { BrowserRouter, Routes, Route, useParams, useLocation, useNavigate } from 'react-router-dom';
import { Navbar } from './components/Navbar';
import { LandingPage } from './pages/LandingPage';
import { CompanionsPage } from './pages/CompanionsPage';
import { RoomPage } from './pages/RoomPage';
import { VideoCallPage } from './pages/VideoCallPage';

// Wrapper for video call page
function VideoCallPageWrapper() {
  const { roomId } = useParams();
  const location = useLocation();
  const navigate = useNavigate();
  
  const companion = location.state?.companion || { id: 'omkar_ai' };
  const userId = location.state?.userId || localStorage.getItem('userId') || `user_${Date.now()}`;

  return (
    <VideoCallPage
      companion={companion}
      roomId={roomId}
      userId={userId}
      onEndCall={() => navigate('/companions')}
    />
  );
}

// Wrapper for companions page
function CompanionsPageWrapper() {
  const navigate = useNavigate();
  
  const handleSelectCompanion = (companion) => {
    console.log('✅ Selected companion:', companion.name);
    const userId = localStorage.getItem('userId') || `user_${Date.now()}`;
    localStorage.setItem('userId', userId);
    
    // Navigate to room creation page
    navigate('/room', {
      state: { companion, userId }
    });
  };

  return (
    <>
      <Navbar showNav={true} showBackButton={false} onBack={() => navigate('/')} />
      <div className="pt-16">
        <CompanionsPage onSelectCompanion={handleSelectCompanion} />
      </div>
    </>
  );
}

// Wrapper for room page
function RoomPageWrapper() {
  const location = useLocation();
  const navigate = useNavigate();
  
  const companion = location.state?.companion || { id: 'omkar_ai', name: 'AI Tutor' };
  const userId = location.state?.userId || localStorage.getItem('userId') || `user_${Date.now()}`;

  const handleJoinRoom = (roomId) => {
    console.log('✅ Joining room:', roomId);
    // ✅ Add companionId to URL
    navigate(`/video/${roomId}?companion=${companion.id}`, {
      state: { companion, userId, roomId }
    });
  };

  return (
    <>
      <Navbar showNav={true} showBackButton={true} onBack={() => navigate('/companions')} />
      <div className="pt-16">
        <RoomPage
          companion={companion}
          userId={userId}
          onJoinRoom={handleJoinRoom}
          onBack={() => navigate('/companions')}
        />
      </div>
    </>
  );
}

// Landing page wrapper
function LandingPageWrapper() {
  const navigate = useNavigate();
  
  return <LandingPage onNavigate={() => navigate('/companions')} />;
}

function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/" element={<LandingPageWrapper />} />
        <Route path="/companions" element={<CompanionsPageWrapper />} />
        <Route path="/room" element={<RoomPageWrapper />} />
        <Route path="/video/:roomId" element={<VideoCallPageWrapper />} />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
